 public static void Run(Scene scene,MiningOperation3D op,Action<bool,string> check)
 {
  var trade=op.GameObject.GetComponent<MiningTrade3D>()!;
  foreach(var node in trade.Research)
  {
   int rank=trade.ResearchRank(node.Id);int baseCost=node.RankCosts.Length>0?node.RankCosts[Math.Min(rank,node.RankCosts.Length-1)]:node.Cost;
   check(trade.ResearchCost(node.Id)==(baseCost<=0?0:Math.Max(1,(int)Math.Round(baseCost*.8f,MidpointRounding.AwayFromZero))),"upgrade discount: "+node.Id);
  }
  MiningCombatMarketCheck.Run(scene,op,check);
  void Set(object o,string p,object? v)=>o.GetType().GetProperty(p)!.SetValue(o,v);
  var feel=op.GameObject.GetComponent<MiningGameFeel3D>()??throw new Exception("Missing selected game-feel component");var player=scene.FindGameObject(op.PlayerObjectId)!;feel.Tick(.01f);
  int hits=feel.ConfirmedHits,kills=feel.ConfirmedKills;
  var enemy=scene.CreateGameObject("Feedback target");enemy.Transform.WorldPosition=new(500,1,-4);enemy.AddComponent(new BoxCollider3D{Size=Vector3.One});enemy.AddComponent(new SimpleEnemyAI3D{Enabled=false});var hp=enemy.AddComponent(new HealthComponent{MaxHealth=40,CurrentHealth=40});
  var fixture=scene.CreateGameObject("Feedback weapon fixture");fixture.Transform.WorldPosition=new(500,1,0);var def=fixture.AddComponent(new WeaponDefinition3D{ShotMode=WeaponShotMode.Hitscan,DamagePerPellet=25,MagazineCapacity=20,SpreadDegrees=0,AccuracyDegrees=0,MovingInaccuracyDegrees=0,ShowShotTrace=false,MuzzleFlashEnabled=false,Range=20});var weapon=fixture.AddComponent(new WeaponInstance3D());weapon.Equip(true);weapon.SetAmmo(20,0);weapon.DamageConfirmed+=feel.ConfirmDamage;
  void Fire(){typeof(WeaponInstance3D).GetField("_cooldown",BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(weapon,0f);check(weapon.Fire(new(500,1,0),-Vector3.UnitZ,player),"feedback test weapon fires");}
  Fire();check(feel.ConfirmedHits==hits+1&&feel.ConfirmedKills==kills&&feel.HitMarkerVisible,"hitscan confirmation requires actual enemy health loss");Fire();check(feel.ConfirmedKills==kills+1&&feel.KillMarkerVisible&&hp.IsDead,"lethal impact produces a distinct confirmed kill");int before=feel.ConfirmedHits;Fire();check(feel.ConfirmedHits==before,"hitting an already dead target does not falsely confirm damage");hp.Revive();hp.Invulnerable=true;Fire();check(feel.ConfirmedHits==before,"invulnerable enemy does not produce a hit confirmation");
  hp.Invulnerable=false;enemy.Active=false;var wall=scene.CreateGameObject("Feedback wall");wall.Transform.WorldPosition=new(500,1,-7);wall.AddComponent(new BoxCollider3D());Fire();check(feel.ConfirmedHits==before,"a scenery impact produces no enemy hit marker");enemy.Active=true;hp.Revive();
  def.ShotMode=WeaponShotMode.Projectile;def.ProjectileSpeed=50;def.ProjectileBlueprint=ByteEngine.Core.Assets.AssetReference.Empty;Fire();var bullet=scene.GameObjects.Last(o=>o.GetComponent<Projectile3D>()?.OwnerId==player.Id).GetComponent<Projectile3D>()!;typeof(Projectile3D).GetMethod("Simulate",BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(bullet,[.2f]);check(feel.ConfirmedHits==before+1&&hp.CurrentHealth==15,"physical projectile forwards actual damage exactly once to its firing weapon");
  var region=scene.CreateGameObject("Explicit damage region").AddComponent(new DamageRegion3D{HealthOwnerId=enemy.Id,IsWeakPoint=false});var receipt=CombatDamageReceipt.Apply(region.GameObject,4,Vector3.UnitX);check(receipt?.Amount==4&&receipt?.TargetId==enemy.Id,"explicit damage regions report the correct owning health component");
  var playerHealth=player.GetComponent<HealthComponent>()!;float oldHp=playerHealth.CurrentHealth;playerHealth.Damage(1,Vector3.UnitX);check(feel.HurtVisible&&playerHealth.LastDamageDirection==Vector3.UnitX,"player damage supplies a directional hurt cue");feel.Tick(.05f);check(feel.MachineGain<1&&feel.MusicGain<1,"combat feedback ducks machinery and music without changing mixer preferences");playerHealth.CurrentHealth=oldHp;
  feel.AddCameraImpulse(20);check(feel.CurrentKickDegrees<=feel.MaximumKickDegrees,"camera impulses are bounded during dense combat");var camera=scene.ActiveCamera!;var view=camera.GetViewMatrix();var aim=camera.ScreenPointToRay(new(.5f),16f/9).Direction;typeof(MiningGameFeel3D).GetMethod("OnLateUpdate",BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(feel,null);check(camera.GetViewMatrix()==view&&camera.ScreenPointToRay(new(.5f),16f/9).Direction==aim&&camera.PresentationRotationOffset!=Quaternion.Identity,"presentation kick leaves authoritative camera aim and transforms unchanged");feel.ShakeIntensity=0;typeof(MiningGameFeel3D).GetMethod("OnLateUpdate",BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(feel,null);check(camera.PresentationRotationOffset==Quaternion.Identity,"zero camera-shake setting fully disables presentation kick");feel.ShakeIntensity=1;
  int credits=op.Credits;op.RefundResearchCredits(17);feel.Tick(.01f);check(feel.CreditGain>=17&&feel.DisplayedCredits<=op.Credits,"credit reward feedback counts toward the actual settled payout");Set(op,"Credits",credits);feel.Tick(.01f);
  var bucket=scene.FindGameObject(feel.AmmoBucketObjectId)!.GetComponent<MiningAmmoBucket3D>()!;long sequence=bucket.CollectionSequence;Set(bucket,"LastCollected",9);Set(bucket,"CollectionSequence",sequence+1);feel.Tick(.01f);check(feel.AmmoGain==9,"ammo popup shows the actual received quantity");Set(bucket,"CollectionSequence",sequence);Set(bucket,"LastCollected",0);
  int rounds=op.CompletedRounds;Set(op,"CompletedRounds",rounds+1);feel.Tick(.01f);check(feel.RoundResult.Contains("COMPLETE")&&feel.RoundResult.Contains("RIG"),"round result includes extraction completion and rig condition");Set(op,"CompletedRounds",rounds);feel.Tick(3);feel.Tick(3);check(!feel.HitMarkerVisible&&!feel.KillMarkerVisible&&!feel.HurtVisible&&feel.CurrentKickDegrees==0&&feel.MachineGain>.99f,"temporary feedback expires and audio gain recovers without global slow motion");
  var preferences=typeof(MiningPauseMenu3D).GetNestedType("Preferences",BindingFlags.NonPublic)!;var oldSave=JsonSerializer.Deserialize("{\"Master\":1,\"Music\":1,\"Sfx\":1,\"Ui\":1,\"Sensitivity\":0.12,\"Keys\":{}}",preferences)!;check(((float)preferences.GetProperty("ShakeIntensity")!.GetValue(oldSave)!)==1,"older settings files retain a safe default for the new shake slider");
  var menu=op.GameObject.GetComponent<MiningPauseMenu3D>()!;var camp=player.GetComponent<MiningCampLayout3D>()!;var widget=scene.FindGameObject(camp.EditButtonObjectId)!.GetComponent<UiWidget>()!;bool visible=widget.Visible,interactive=widget.Interactable;menu.Open();check(!widget.Visible&&!widget.Interactable,"gameplay widgets cannot overlap or intercept clicks on the pause settings");menu.Resume();check(widget.Visible==visible&&widget.Interactable==interactive,"resuming restores prior gameplay widget state");
  var spiderRoot=RuntimeSpawnService.SpawnBlueprint(scene,op.RaiderBlueprint,scene.FindGameObject(op.DrillObjectId)!.Transform.WorldPosition+new Vector3(0,0,2))!;op.ConfigureEnemy(spiderRoot,false);var spider=spiderRoot.GetComponent<MiningSpiderAnimation3D>()!;var skin=spider.Renderer!;var original=skin.GetMaterialOverrides(0).EmissionColor;spiderRoot.GetComponent<HealthComponent>()!.Damage(1,Vector3.UnitX);check(MiningAudio3D.Find(op.GameObject)?.LastCue=="SpiderHit","damaged spider plays its spatial hit cue");typeof(MiningSpiderAnimation3D).GetMethod("TickHitFeedback",BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(spider,[.02f]);check(spider.HitResponseActive&&skin.GetMaterialOverrides(0).EmissionColor==spider.HitFlashColor,"actual animated spider receives a renderer-local hit flash");typeof(MiningSpiderAnimation3D).GetMethod("TickHitFeedback",BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(spider,[1f]);check(!spider.HitResponseActive&&skin.GetMaterialOverrides(0).EmissionColor==original,"spider flash restores its inherited material rather than changing shared assets");
  Set(spiderRoot.GetComponent<SimpleEnemyAI3D>()!,"AttackPhase","Windup");var brain=spiderRoot.GetComponent<ByteEngine.Core.AI.AIBehavior3D>()!;brain.TargetObjectId=player.Id;feel.Tick(.3f);check(feel.VisibleRigWarnings==0,"attacking another nearby target does not falsely warn of a rig strike");brain.TargetObjectId=op.DrillObjectId;float drillHp=scene.FindGameObject(op.DrillObjectId)!.GetComponent<HealthComponent>()!.CurrentHealth;feel.Tick(.3f);check(feel.VisibleRigWarnings>0&&scene.FindGameObject(op.DrillObjectId)!.GetComponent<HealthComponent>()!.CurrentHealth==drillHp,"rig-strike tell follows windup without applying premature damage");feel.Tick(.6f);check(feel.VisibleRigWarnings==0,"a held windup does not repeatedly restart its warning every frame");spiderRoot.GetComponent<HealthComponent>()!.Damage(100000,Vector3.UnitX);check(MiningAudio3D.Find(op.GameObject)?.LastCue=="SpiderDeath","dying spider plays its separate death cue");scene.DestroyGameObject(spiderRoot);
  weapon.DamageConfirmed-=feel.ConfirmDamage;scene.DestroyGameObject(fixture);scene.DestroyGameObject(enemy);scene.DestroyGameObject(wall);scene.DestroyGameObject(region.GameObject);
 }
